CREATE TYPE "ContentType" AS ENUM ('POST', 'PAGE');
CREATE TYPE "ContentStatus" AS ENUM ('DRAFT', 'SCHEDULED', 'PUBLISHED', 'ARCHIVED');
CREATE TYPE "ResetTokenStatus" AS ENUM ('ACTIVE', 'USED');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY, "email" TEXT NOT NULL UNIQUE, "passwordHash" TEXT NOT NULL, "name" TEXT NOT NULL DEFAULT 'Administrator', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Media" ("id" TEXT PRIMARY KEY, "filename" TEXT NOT NULL, "originalName" TEXT NOT NULL, "path" TEXT NOT NULL UNIQUE, "url" TEXT NOT NULL, "mimeType" TEXT NOT NULL, "extension" TEXT NOT NULL, "size" BIGINT NOT NULL, "checksum" TEXT NOT NULL, "width" INTEGER, "height" INTEGER, "duration" DOUBLE PRECISION, "altText" TEXT NOT NULL DEFAULT '', "caption" TEXT NOT NULL DEFAULT '', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "Content" ("id" TEXT PRIMARY KEY, "type" "ContentType" NOT NULL, "status" "ContentStatus" NOT NULL DEFAULT 'DRAFT', "title" TEXT NOT NULL, "slug" TEXT NOT NULL, "excerpt" TEXT NOT NULL DEFAULT '', "markdown" TEXT NOT NULL DEFAULT '', "html" TEXT NOT NULL DEFAULT '', "wordCount" INTEGER NOT NULL DEFAULT 0, "coverMediaId" TEXT, "tags" TEXT[] DEFAULT ARRAY[]::TEXT[], "seoTitle" TEXT, "seoDescription" TEXT, "publishedAt" TIMESTAMP(3), "scheduledAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Content_coverMediaId_fkey" FOREIGN KEY ("coverMediaId") REFERENCES "Media"("id") ON DELETE SET NULL);
CREATE TABLE "PasswordResetToken" ("id" TEXT PRIMARY KEY, "tokenHash" TEXT NOT NULL UNIQUE, "status" "ResetTokenStatus" NOT NULL DEFAULT 'ACTIVE', "expiresAt" TIMESTAMP(3) NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "userId" TEXT NOT NULL, CONSTRAINT "PasswordResetToken_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "Content_type_slug_key" ON "Content"("type", "slug"); CREATE INDEX "Content_type_status_publishedAt_idx" ON "Content"("type", "status", "publishedAt"); CREATE INDEX "Content_updatedAt_idx" ON "Content"("updatedAt"); CREATE INDEX "Media_createdAt_idx" ON "Media"("createdAt"); CREATE INDEX "PasswordResetToken_userId_status_idx" ON "PasswordResetToken"("userId", "status");
